#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill for ticket 71 (spec 385): the maintainer's steps for the backend.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: the human steps of ticket 71, one phase per run (the agent's steps sit between them).
#
#   bash scripts/backend-wizard.sh h1   Cloudflare account: 2FA, card, R2, Zero Trust, billing, account id
#   bash scripts/backend-wizard.sh h2   Tokens: Wrangler login, the CI token and variable in GitHub
#   bash scripts/backend-wizard.sh h3   Access, Google, Turnstile, Telegram, UptimeRobot, Healthchecks.io
#   bash scripts/backend-wizard.sh h4   The weekly backup on the Flint 2 (needs the agent's step A4 first)
#
# No secret is ever typed into the chat, a file or a log. A secret goes from your keyboard straight to its owner:
# `wrangler secret put` (Cloudflare), `gh secret set` (GitHub), or one ssh pipe to a root-only file on the router.
# Only ids, site keys and host names (not secret) are saved, in backend-handoff.local (gitignored), for the agent.
# ──────────────────────────────────────────────────────────────────────────

ENV_FILE="${BACKEND_HANDOFF:-backend-handoff.local}"
GOOGLE_CALLBACK_PATH="/api/auth/google/callback" # provisional: ticket 78 owns the final path, and Google lets you edit it
BACKUP_CONF="/etc/bd-beads-backup.conf"          # the contract with the agent's backup script (step A4)
BACKUP_BIN="/usr/bin/bd-beads-backup"

# put_secret NAME ENV: wrangler asks for the value itself, hidden, and sends it straight to Cloudflare.
put_secret() {
  say "Wrangler will ask for $1 for the $2 Worker. Paste it there; it is hidden and goes straight to Cloudflare."
  npx wrangler secret put "$1" --env "$2" || {
    warn "wrangler could not set $1 for $2 (is the Worker deployed and are you logged in?)"
    SKIPPED+=("Cloudflare secret $1 for $2: npx wrangler secret put $1 --env $2")
  }
}
put_secret_both() { put_secret "$1" dev; put_secret "$1" production; }

# gh_env_secret NAME: gh asks for the value itself, hidden, and sends it straight to the production environment.
gh_env_secret() {
  gh secret set "$1" --env production || {
    warn "gh could not set $1"
    SKIPPED+=("GitHub environment secret $1: gh secret set $1 --env production")
  }
}
gh_env_var() {
  gh variable set "$1" --env production --body "$2" || {
    warn "gh could not set $1"
    SKIPPED+=("GitHub environment variable $1: gh variable set $1 --env production --body <value>")
  }
}

phase_h1() {
  stage "Cloudflare: sign-in security"
  say "A stolen login could bill you or empty the account, so this comes first."
  open_url "https://dash.cloudflare.com/profile/authentication"
  step "Turn on two-factor authentication (an authenticator app or a security key)."
  step "Save the recovery codes in your password manager."
  pause "Two-factor is on? Press Enter."

  stage "Cloudflare: R2 and the card"
  say "R2 needs a card on file even on its free allowance. Nothing is charged inside the free allowance."
  open_url "https://dash.cloudflare.com/?to=/:account/r2/overview"
  step "Add the card if it asks (Billing → Payment info), then enable R2 on the free plan."
  step "Do NOT add any paid add-on, and do not choose Workers Paid."
  note "The wording of these pages changes; the point is R2 enabled, nothing paid."
  pause "R2 is enabled? Press Enter."

  stage "Cloudflare: Zero Trust (Access)"
  say "Access puts a sign-in in front of both Workers until the public release."
  open_url "https://one.dash.cloudflare.com/"
  step "If asked, choose a team name (it becomes <team>.cloudflareaccess.com) and the Free plan."
  step "It may ask for the card again: that is fine on the Free plan."
  ask CF_ACCESS_TEAM_NAME "Your team name:"
  write_env CF_ACCESS_TEAM_NAME "$CF_ACCESS_TEAM_NAME"

  stage "Cloudflare: billing check"
  open_url "https://dash.cloudflare.com/?to=/:account/billing/subscriptions"
  step "Open Billing → Subscriptions."
  step "It must list nothing paid. If anything is, cancel it."
  confirm "Does it show no paid subscription?" || { warn "Fix this before going on; re-run this phase."; exit 1; }

  stage "Cloudflare: the account id"
  say "The account id is not a secret; the agent needs it to create resources."
  open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
  step "On this page, copy the Account ID from the right-hand column."
  ask CLOUDFLARE_ACCOUNT_ID "Paste the account id:"
  write_env CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
  say "Tell the agent: \"H1 done\". The ids are in $ENV_FILE."
}

phase_h2() {
  stage "Wrangler: log in on this machine"
  say "This lets the agent create the databases and buckets from here. The login stays on this machine."
  step "A browser opens; allow Wrangler."
  npx wrangler login
  npx wrangler whoami

  stage "Cloudflare: the CI token"
  say "CI deploys with this token. It must reach this account only, and only Workers Scripts and D1."
  open_url "https://dash.cloudflare.com/profile/api-tokens"
  step "Create Token → Create Custom Token. Name it bd-beads-ci."
  step "Permissions: Account → Workers Scripts → Edit; Account → D1 → Edit. Nothing else."
  step "Account Resources: Include → this one account only. Leave Client IP filtering and TTL as you prefer."
  step "Create the token and keep its page open: the next stage takes it."
  pause "Token created and visible? Press Enter."

  stage "GitHub: the token and the account id"
  say "Both go into the 'production' environment, which is limited to the main branch."
  if ! gh api "repos/{owner}/{repo}/environments/production" >/dev/null 2>&1; then
    warn "The 'production' environment doesn't exist yet."
    step "GitHub → Settings → Environments → New environment → production."
    step "Deployment branches and tags → Selected branches → main."
    pause "Created? Press Enter."
  fi
  say "gh will ask for the token (hidden). Paste it there."
  gh_env_secret CLOUDFLARE_API_TOKEN
  ask CLOUDFLARE_ACCOUNT_ID "Account id (from phase h1):"
  write_env CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
  gh_env_var CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
  say "Tell the agent: \"H2 done\"."
}

phase_h3() {
  stage "The two Worker addresses"
  say "The agent deployed both Workers in step A2 and gave you their workers.dev addresses."
  ask WORKER_HOST_DEV "Dev host (bd-beads-dev.<subdomain>.workers.dev):"
  ask WORKER_HOST_PRODUCTION "Production host (bd-beads.<subdomain>.workers.dev):"
  write_env WORKER_HOST_DEV "$WORKER_HOST_DEV"
  write_env WORKER_HOST_PRODUCTION "$WORKER_HOST_PRODUCTION"

  stage "Access (H3a): protect both Workers"
  open_url "https://one.dash.cloudflare.com/"
  step "Access → Applications → Add an application → Self-hosted. One application per host:"
  step "  $WORKER_HOST_DEV, and then $WORKER_HOST_PRODUCTION."
  step "Policy: Allow, include Emails: yours, then each tester's. Login method: One-time PIN."
  step "Then add a second application per host for the path /api/health, with one policy: Bypass, include Everyone."
  note "The more specific path wins, so health answers without a login and nothing else does."
  step "Open each host in a private window: you should get the Access sign-in, and /api/health should answer."
  confirm "Does it behave like that on both hosts?" || warn "Not confirmed: fix it before telling the agent."
  ask ACCESS_HOST_DEV "Dev host exactly as it looks after Access:"
  ask ACCESS_HOST_PRODUCTION "Production host exactly as it looks after Access:"
  write_env ACCESS_HOST_DEV "$ACCESS_HOST_DEV"
  write_env ACCESS_HOST_PRODUCTION "$ACCESS_HOST_PRODUCTION"

  stage "Google (H3b): the project and the consent screen"
  open_url "https://console.cloud.google.com/projectcreate"
  step "Create a project named bd-beads."
  open_url "https://console.cloud.google.com/auth/overview"
  step "Set up the consent screen: app name bd-beads, your email as support and developer contact, audience External."
  step "Publishing status must stay Testing. Add yourself (and any tester) as a test user."
  step "Scopes: only openid, email and profile (the default ones). Nothing else."
  pause "Consent screen done, in Testing? Press Enter."

  stage "Google (H3b): the OAuth client"
  open_url "https://console.cloud.google.com/auth/clients/create"
  step "Application type: Web application. Name: bd-beads."
  say "Authorized redirect URIs (add all four; ticket 78 may change the path later and you can edit them):"
  say "  https://$WORKER_HOST_DEV$GOOGLE_CALLBACK_PATH"
  say "  https://$WORKER_HOST_PRODUCTION$GOOGLE_CALLBACK_PATH"
  say "  http://localhost:5173$GOOGLE_CALLBACK_PATH"
  say "  http://localhost:8787$GOOGLE_CALLBACK_PATH"
  if confirm "Did the console accept the workers.dev addresses?"; then
    write_env GOOGLE_WORKERS_DEV_REDIRECT accepted
  else
    write_env GOOGLE_WORKERS_DEV_REDIRECT rejected
    warn "Keep only the two localhost addresses. Ticket 390 decides whether to buy the domain early."
  fi
  ask GOOGLE_CLIENT_ID "Paste the client id (not secret):"
  write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
  step "Now copy the client secret from the same page; wrangler asks for it next, twice (dev, then production)."
  put_secret_both GOOGLE_CLIENT_SECRET

  stage "Turnstile (H3c)"
  open_url "https://dash.cloudflare.com/?to=/:account/turnstile"
  step "Add widget, name bd-beads. Hostnames: $WORKER_HOST_DEV, $WORKER_HOST_PRODUCTION and localhost."
  step "Widget mode: Managed. Pre-clearance: no."
  ask TURNSTILE_SITE_KEY "Paste the site key (not secret):"
  write_env TURNSTILE_SITE_KEY "$TURNSTILE_SITE_KEY"
  step "Copy the secret key; wrangler asks for it next, twice."
  put_secret_both TURNSTILE_SECRET_KEY

  stage "Telegram (H3d)"
  open_url "https://t.me/BotFather"
  step "Send /newbot and follow it. Copy the bot token it gives you (keep it out of the chat)."
  step "Open your new bot and send it any message."
  say "Find your chat id: open https://api.telegram.org/bot<TOKEN>/getUpdates in your browser (put your token in)."
  step "Look for \"chat\":{\"id\": 123456789 ...}: that number is the chat id."
  step "Wrangler asks for the token and then the chat id, for each Worker."
  put_secret_both TELEGRAM_BOT_TOKEN
  put_secret_both TELEGRAM_CHAT_ID

  stage "UptimeRobot (H3e)"
  open_url "https://dashboard.uptimerobot.com/monitors"
  step "Add two HTTP(s) monitors, interval 5 minutes:"
  step "  https://$WORKER_HOST_DEV/api/health and https://$WORKER_HOST_PRODUCTION/api/health"
  step "Alert contacts: your email, and the UptimeRobot phone app (install it and log in; it sends the push)."
  pause "Both monitors are up and green? Press Enter."

  stage "Healthchecks.io (H3e)"
  open_url "https://healthchecks.io/projects/"
  step "Integrations → add Telegram and follow it (or reuse your bot's chat)."
  step "Create three checks and tick the Telegram integration on each:"
  step "  watchdog-dev: period 15 minutes, grace 1 hour"
  step "  watchdog-production: period 15 minutes, grace 1 hour"
  step "  backup-weekly: period 7 days, grace 1 day (its ping URL is used in phase h4)"
  say "Each check's ping URL: wrangler asks for the dev one, then the production one."
  put_secret HEALTHCHECK_URL dev
  put_secret HEALTHCHECK_URL production

  stage "Analytics token (H3e, only if the agent said to use GraphQL)"
  if confirm "Did the agent say the watchdog should read Cloudflare's analytics (USAGE_SOURCE=graphql)?"; then
    open_url "https://dash.cloudflare.com/profile/api-tokens"
    step "Create a custom token, name bd-beads-analytics: Account → Account Analytics → Read. Nothing else, this account only."
    put_secret_both CF_ANALYTICS_TOKEN
  else
    note "Skipped: the watchdog keeps its own counters in D1."
  fi
  say "Tell the agent: \"H3 done\". The ids and site key are in $ENV_FILE."
}

phase_h4() {
  stage "Before you start"
  if [[ ! -f scripts/backup-d1.sh ]]; then
    warn "scripts/backup-d1.sh doesn't exist yet: the agent writes it in step A4, before this phase."
    exit 1
  fi
  say "This phase puts the weekly backup on the Flint 2: export, encrypt, keep four, ping."
  say "It needs on the router: age and curl (the script checks and says what to opkg install)."
  ask FLINT_HOST "ssh target of the Flint 2 (user@host, kept only for this run):"

  stage "age: the key pair, on your own computer"
  step "Install age if needed, then run: age-keygen -o bd-beads-backup.key"
  step "Put that file's contents in your password manager, then delete the file. The private key never goes on the router."
  step "The line starting 'Public key: age1…' is the public key."
  ask AGE_PUBLIC_KEY "Paste the public key (age1...):"
  [[ "$AGE_PUBLIC_KEY" == age1* ]] || { warn "That doesn't look like an age public key."; exit 1; }

  stage "Cloudflare: the export token"
  open_url "https://dash.cloudflare.com/profile/api-tokens"
  step "Create a custom token, name bd-beads-backup: Account → D1 → Edit (the export is a POST; the agent confirms in A4 if a narrower scope exists)."
  step "Account Resources: this one account only. Cloudflare can't scope a token to one database."
  ask D1_DATABASE_ID "Production D1 database id (the agent gives it; not secret):"
  ask BACKUP_PING_URL "The backup-weekly check's ping URL:"

  stage "The Flint 2: install"
  say "The token goes from your keyboard to a root-only file on the router in one ssh pipe."
  ask_secret BACKUP_TOKEN "Paste the export token (hidden):"
  printf 'CLOUDFLARE_API_TOKEN=%s\nCLOUDFLARE_ACCOUNT_ID=%s\nD1_DATABASE_ID=%s\nAGE_PUBLIC_KEY=%s\nHEALTHCHECK_URL=%s\n' \
    "$BACKUP_TOKEN" "${CLOUDFLARE_ACCOUNT_ID:-$(_existing CLOUDFLARE_ACCOUNT_ID)}" "$D1_DATABASE_ID" "$AGE_PUBLIC_KEY" "$BACKUP_PING_URL" \
    | ssh "$FLINT_HOST" "umask 077 && cat > $BACKUP_CONF"
  ssh "$FLINT_HOST" "cat > $BACKUP_BIN && chmod 700 $BACKUP_BIN" < scripts/backup-d1.sh
  ssh "$FLINT_HOST" "grep -q '$BACKUP_BIN' /etc/crontabs/root 2>/dev/null || echo '17 3 * * 0 $BACKUP_BIN' >> /etc/crontabs/root; /etc/init.d/cron restart"
  unset BACKUP_TOKEN
  write_env D1_DATABASE_ID "$D1_DATABASE_ID"
  write_env AGE_PUBLIC_KEY "$AGE_PUBLIC_KEY"

  stage "Run it once"
  step "Running the backup now on the router; this takes a moment."
  ssh "$FLINT_HOST" "$BACKUP_BIN"
  step "Check Healthchecks.io: backup-weekly shows a fresh ping."
  pause "Do you see the ping, and an encrypted file on the USB stick? Press Enter."
  say "Tell the agent: \"H4 done\"."
}

case "${1:-}" in
  h1) TOTAL_STAGES=5; banner "Backend H1: the Cloudflare account"; phase_h1 ;;
  h2) TOTAL_STAGES=3; banner "Backend H2: tokens"; phase_h2 ;;
  h3) TOTAL_STAGES=9; banner "Backend H3: sign-in, bots and alerts"; phase_h3 ;;
  h4) TOTAL_STAGES=5; banner "Backend H4: the weekly backup"; phase_h4 ;;
  *) echo "Usage: bash scripts/backend-wizard.sh h1|h2|h3|h4   (the phases of ticket 71, in order)"; exit 2 ;;
esac

finish
